// Load the Renderer2DData asset directly
var assets = UnityEditor.AssetDatabase.FindAssets("t:Renderer2DData");
foreach (var guid in assets)
{
    var path = UnityEditor.AssetDatabase.GUIDToAssetPath(guid);
    var rd = UnityEditor.AssetDatabase.LoadAssetAtPath<Renderer2DData>(path);
    if (rd != null)
    {
        Debug.Log($"[R2D] Found: {rd.name} at {path}");
        var so = new UnityEditor.SerializedObject(rd);
        var shadowProp = so.FindProperty("m_Shadows.m_Enabled");
        if (shadowProp != null)
        {
            Debug.Log($"[R2D] Shadows Enabled: {shadowProp.boolValue}");
        }
        else
        {
            Debug.Log("[R2D] m_Shadows.m_Enabled not found, searching all props...");
            var prop = so.GetIterator();
            bool enter = true;
            while (prop.Next(enter))
            {
                if (prop.propertyPath.ToLower().Contains("shadow"))
                {
                    Debug.Log($"[R2D] {prop.propertyPath} = {prop.boolValue} (type={prop.propertyType})");
                }
                enter = true;
            }
        }
    }
}

